  width: 90vw;
  max-width: 960px;
  height: 80vh;
  max-height: 640px;
  background: var(--term-bg);
  border: 2px solid var(--term-border);
  box-shadow: 0 0 40px rgba(0, 255, 102, 0.25), inset 0 0 50px rgba(0, 0, 0, 0.8);
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  border-radius: 6px;
  transform: scale(0.95);
  transition: transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

#v1r3-soc-modal.active .v1r3-terminal-window {
  transform: scale(1);
}

/* CRT Scanlines Overlay */
.v1r3-terminal-window::before {
  content: " ";
  display: block;
  position: absolute;
  top: 0; left: 0; bottom: 0; right: 0;
  background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.03), rgba(0, 255, 0, 0.01), rgba(0, 0, 255, 0.03));
  z-index: 20;
  background-size: 100% 3px, 3px 100%;
  pointer-events: none;
}

/* Terminal Titlebar */
.v1r3-term-header {
  background: rgba(0, 255, 102, 0.1);
  border-bottom: 1px solid var(--term-border);
  padding: 10px 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--term-font);
  font-size: 12px;
  color: var(--term-text);
  letter-spacing: 1px;
}

.v1r3-term-title {
  display: flex;
  align-items: center;
  gap: 8px;
}

.v1r3-term-controls {
  display: flex;
  gap: 8px;
}

.v1r3-term-btn {
  background: transparent;
  border: 1px solid var(--term-dim);
  color: var(--term-text);
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 10px;
  transition: all 0.2s;
}

.v1r3-term-btn:hover {
  background: var(--term-accent);
  border-color: var(--term-accent);
  color: #fff;
}

/* Terminal Body Output & Input */
.v1r3-term-body {
  flex: 1;
  padding: 20px;
  overflow-y: auto;
  font-family: var(--term-font);
  font-size: 13px;
  line-height: 1.5;
  color: var(--term-text);
  display: flex;
  flex-direction: column;
  gap: 12px;
  scroll-behavior: smooth;
}

.v1r3-term-body::-webkit-scrollbar {
  width: 6px;
}
.v1r3-term-body::-webkit-scrollbar-track {
  background: rgba(0,0,0,0.5);
}
.v1r3-term-body::-webkit-scrollbar-thumb {
  background: var(--term-dim);
  border-radius: 3px;
}

.term-output-line {
  white-space: pre-wrap;
  word-break: break-all;
}

.term-prompt-line {
  display: flex;
  align-items: center;
  gap: 8px;
}

.term-user {
  color: var(--term-cyan);
  font-weight: bold;
}

.term-host {
  color: var(--term-yellow);
}

.term-path {
  color: var(--term-text);
}

.term-input {
  flex: 1;
  background: transparent;
  border: none;
  color: var(--term-text);
  font-family: var(--term-font);
  font-size: 13px;
  outline: none;
  caret-color: var(--term-text);
}

/* Helpers & Colors for Output */
.text-success { color: #00ff66; font-weight: bold; }
.text-warn { color: #f3e600; font-weight: bold; }
.text-error { color: #ff0055; font-weight: bold; }
.text-info { color: #00f0ff; }
.text-dim { color: #557766; }

/* Responsive adjustments */
@media (max-width: 768px) {
  .v1r3-terminal-window {
    width: 95vw;
    height: 85vh;
  }
  #v1r3-soc-trigger {
    bottom: 16px;
    right: 16px;
    padding: 8px 12px;
    font-size: 11px;
  }
}
```

