### 3. Motor de la Terminal (`/assets/functions/Terminal/TerminalEngine.js`)

Este fichero maneja la lógica de comandos, eventos de teclado, autocompletado con `Tab`, historial con flechas y simulaciones interactivas.

```javascript
/* =================================================================
 * V1R3-SEC-OPS: Terminal Engine & Event Controller
 * Absolute Path: /assets/functions/Terminal/TerminalEngine.js
 * ================================================================= */

import { TERMINAL_CONFIG, HELP_COMMANDS, NEOFETCH_ASCII, SKILLS_MATRIX_DATA, AUDIT_STEPS, SQL_MOCK_DB, CTF_CHALLENGE_DATA } from './challengesData.js';

export class TerminalEngine {
  constructor() {
    this.history = [];
    this.historyIndex = -1;
    this.activeChallenge = false;
    this.isMatrixRunning = false;
    this.matrixInterval = null;
  }

  init() {
    this.injectDOM();
    this.bindEvents();
    this.printBanner();
  }

  injectDOM() {
    if (document.getElementById('v1r3-soc-modal')) return;

    const triggerHTML = `
      <button id="v1r3-soc-trigger" aria-label="Abrir Terminal SOC">
        <span class="status-dot"></span>
        <span>[SOC: ONLINE]</span>
      </button>
    `;

    const modalHTML = `
      <div id="v1r3-soc-modal" role="region" aria-label="V1R3 SEC-OPS Terminal">
        <div class="v1r3-terminal-window">
          <div class="v1r3-term-header">
            <div class="v1r3-term-title">
              <span>⚡ V1R3-SEC-OPS v4.2.0 [Secure Shell]</span>
            </div>
            <div class="v1r3-term-controls">
              <button class="v1r3-term-btn" id="v1r3-term-minimize" title="Minimizar">_</button>
              <button class="v1r3-term-btn" id="v1r3-term-close" title="Cerrar">✕</button>
            </div>
          </div>
          <div class="v1r3-term-body" id="v1r3-term-output">
            <!-- Output lines appended dynamically -->
          </div>
          <div class="term-prompt-line" style="padding: 0 20px 20px 20px; background: var(--term-bg);">
            <span class="term-user">${TERMINAL_CONFIG.user}</span>@<span class="term-host">${TERMINAL_CONFIG.host}</span>:<span class="term-path">${TERMINALConfigPath()}</span><span style="color:var(--term-text);">$</span>
            <input type="text" id="v1r3-term-input" class="term-input" autofocus autocomplete="off" spellcheck="false" />
          </div>
        </div>
      </div>
    `;

    document.body.insertAdjacentHTML('beforeend', triggerHTML);
    document.body.insertAdjacentHTML('beforeend', modalHTML);
  }

  bindEvents() {
    const trigger = document.getElementById('v1r3-soc-trigger');
    const modal = document.getElementById('v1r3-soc-modal');
    const closeBtn = document.getElementById('v1r3-term-close');
    const minimizeBtn = document.getElementById('v1r3-term-minimize');
    const input = document.getElementById('v1r3-term-input');
    const output = document.getElementById('v1r3-term-output');

    const toggleTerminal = () => {
      modal.classList.toggle('active');
      if (modal.classList.contains('active')) {
        input.focus();
        this.scrollToBottom();
      }
    };

    trigger.addEventListener('click', toggleTerminal);
    closeBtn.addEventListener('click', toggleTerminal);
    minimizeBtn.addEventListener('click', toggleTerminal);

    // Global Hotkeys: Ctrl + ` (backtick) or F4
    window.addEventListener('keydown', (e) => {
      if ((e.ctrlKey && e.key === '`') || e.key === 'F4') {
        e.preventDefault();
        toggleTerminal();
      }
      if (e.key === 'Escape' && modal.classList.contains('active')) {
        modal.classList.remove('active');
        if (this.isMatrixRunning) this.stopMatrix();
      }
    });

    // Click anywhere on modal background closes it
    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        modal.classList.remove('active');
        if (this.isMatrixRunning) this.stopMatrix();
      }
    });

    // Input command handling
    input.addEventListener('keydown', (e) => {
      if (this.isMatrixRunning) {
        this.stopMatrix();
        e.preventDefault();
        return;
      }

      if (e.key === 'Enter') {
        const cmd = input.value.trim();
        if (cmd) {
          this.history.push(cmd);
          this.historyIndex = this.history.length;
          this.printUserCommand(cmd);
          input.value = '';
          this.executeCommand(cmd);
        }
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        if (this.historyIndex > 0) {
          this.historyIndex--;
          input.value = this.history[this.historyIndex];
        }
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        if (this.historyIndex < this.history.length - 1) {
          this.historyIndex++;
          input.value = this.history[this.historyIndex];
        } else {
          this.historyIndex = this.history.length;
          input.value = '';
        }
      } else if (e.key === 'Tab') {
        e.preventDefault();
        this.handleAutoCompletion(input);
      }
    });

    // Focus input when clicking anywhere on terminal body
    output.addEventListener('click', () => {
      input.focus();
    });
  }

  printBanner() {
    const banner = `
<span class="text-success">V1R3-SEC-OPS Security Kernel v4.2.0</span>
Type <span class="text-info">'help'</span> to explore security modules, code sandboxes, and developer tools.
Last login: ${new Date().toUTCString()} on tty1 from 127.0.0.1
`;
    this.appendOutput(banner);
  }

  printUserCommand(cmd) {
    const promptLine = `
      <div class="term-prompt-line">
        <span class="term-user">${TERMINAL_CONFIG.user}</span>@<span class="term-host">${TERMINAL_CONFIG.host}</span>:<span class="term-path">${TERMINALConfigPath()}</span><span style="color:var(--term-text);">$</span>
        <span>${this.escapeHTML(cmd)}</span>
      </div>
    `;
    const output = document.getElementById('v1r3-term-output');
    output.insertAdjacentHTML('beforeend', promptLine);
  }

  appendOutput(html) {
    const output = document.getElementById('v1r3-term-output');
    const div = document.createElement('div');
    div.className = 'term-output-line';
    div.innerHTML = html;
    output.appendChild(div);
    this.scrollToBottom();
  }

  scrollToBottom() {
    const output = document.getElementById('v1r3-term-output');
    output.scrollTop = output.scrollHeight;
  }

  executeCommand(rawCmd) {
    const parts = rawCmd.split(' ');
    const cmd = parts[0].toLowerCase();
    const args = parts.slice(1).join(' ');

    if (this.activeChallenge) {
      this.handleChallengeInput(rawCmd);
      return;
    }

    switch (cmd) {
      case 'help':
        let helpText = "<span class=\"text-warn\">AVAILABLE SECURITY & DEV MODULES:</span>\n\n";
        HELP_COMMANDS.forEach(h => {
          helpText += `  <span class=\"text-info\">${h.cmd.padEnd(28)}</span> ${h.desc}\n`;
        });
        this.appendOutput(helpText);
        break;

      case 'neofetch':
        this.appendOutput(NEOFETCH_ASCII);
        break;

      case 'skills':
        if (args.includes('--matrix')) {
          this.appendOutput(SKILLS_MATRIX_DATA);
        } else {
          this.appendOutput("Usage: skills --matrix");
        }
        break;

      case 'audit':
        if (args.includes('--target=webapp')) {
          this.runAuditSimulation();
        } else {
          this.appendOutput("Usage: audit --target=webapp");
        }
        break;

      case 'sql-query':
        const matchExec = args.match(/--exec="([^"]+)"/);
        if (matchExec && matchExec[1]) {
          const query = matchExec[1].toLowerCase().trim();
          const result = SQL_MOCK_DB[query] || `[INFO] Query executed successfully. 0 rows affected or unsupported mock query.\n[TIP] Try: sql-query --exec="SELECT * FROM users"`;
          this.appendOutput(`<span class="text-info">[SQL-SANDBOX]</span>\n${result}`);
        } else {
          this.appendOutput("Usage: sql-query --exec=\"SELECT * FROM users\"");
        }
        break;

      case 'ctf-challenge':
        this.activeChallenge = true;
        this.appendOutput(`<span class="text-warn">${CTF_CHALLENGE_DATA.prompt}</span>`);
        break;

      case 'matrix':
        this.startMatrix();
        break;

      case 'clear':
        document.getElementById('v1r3-term-output').innerHTML = '';
        break;

      default:
        this.appendOutput(`<span class="text-error">Command not recognized: '${this.escapeHTML(cmd)}'. Type 'help' for available options.</span>`);
        break;
    }
  }

  runAuditSimulation() {
    let index = 0;
    const interval = setInterval(() => {
      if (index < AUDIT_STEPS.length) {
        const step = AUDIT_STEPS[index];
        let className = "text-dim";
        if (step.includes("[SUCCESS]")) className = "text-success";
        else if (step.includes("[WARN]")) className = "text-warn";
        else if (step.includes("[INFO]")) className = "text-info";

        this.appendOutput(`<span class="${className}">${step}</span>`);
        index++;
      } else {
        clearInterval(interval);
      }
    }, 400);
  }

  handleChallengeInput(input) {
    if (input.trim() === CTF_CHALLENGE_DATA.answer) {
      this.appendOutput(`<span class="text-success">${CTF_CHALLENGE_DATA.successMsg}</span>`);
    } else {
      this.appendOutput(`<span class="text-error">[ACCESS DENIED] Incorrect key. Try again or type 'exit' to abort.</span>`);
      if (input.trim() === 'exit') {
        this.activeChallenge = false;
        this.appendOutput("Exited CTF challenge.");
      }
      return;
    }
    this.activeChallenge = false;
  }

  startMatrix() {
    this.isMatrixRunning = true;
    const output = document.getElementById('v1r3-term-output');
    const chars = "01V1R3SECDEFGHJKLMNPQRSTUVWXYZ";
    this.matrixInterval = setInterval(() => {
      let line = "";
      for (let i = 0; i < 60; i++) {
        line += chars.charAt(Math.floor(Math.random() * chars.length));
      }
      output.innerHTML += `<div style="color: #00ff66; font-family: monospace;">${line}</div>`;
      this.scrollToBottom();
    }, 60);
    this.appendOutput("<span class=\"text-info\">[MATRIX MODE] Press any key or ESC to exit.</span>");
  }

  stopMatrix() {
    if (this.matrixInterval) clearInterval(this.matrixInterval);
    this.isMatrixRunning = false;
    this.appendOutput("<span class=\"text-warn\">[MATRIX MODE] Terminated.</span>");
  }

  handleAutoCompletion(inputField) {
    const val = inputField.value.trim().toLowerCase();
    const commands = HELP_COMMANDS.map(h => h.cmd);
    const match = commands.find(c => c.startsWith(val));
    if (match) {
      inputField.value = match;
    }
  }

  escapeHTML(str) {
    return str.replace(/[&<>'"]/g,
      tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
    );
  }
}

function TERMINALConfigPath() {
  return TERMINAL_CONFIG.path;
}
